// Spark sends the escalation payload here
var data = msg.payload;

node.log('Incoming Spark payload: ' + JSON.stringify(data));

// Pull fields out for downstream use
msg.deviceName  = data.cmdb_ci;        // arrives as device NAME, not UUID
msg.callerId    = data.caller_id;
msg.shortDesc   = data.short_description;
msg.description = data.description;
msg.workNotes   = data.work_notes;
msg.category    = data.category;
msg.subcategory = data.subcategory;

return msg;

// Spark expects ticketId + ticketNumber in the response so it can show the
// user a reference and mark the conversation as escalated. We generate our
// own values - no real ticket is created behind the scenes.

const now = Date.now();
const shortId = now.toString(36).toUpperCase();
const ticketNumber = 'has been created and a Rescue Remote Agent would be with you shortly, here is the ticket number-' + shortId;
const ticketId = 'rescue-' + now + '-' + Math.random().toString(36).substring(2, 10);

msg.rescueTicketId = ticketId;
msg.rescueTicketNumber = ticketNumber;

msg.payload = {
    ticketId: ticketId,
    ticketNumber: ticketNumber,
    status: 'accepted',
    message: 'Rescue session triggered',
    receivedAt: new Date().toISOString()
};
msg.statusCode = 200;

return msg;

if (!msg.deviceName) {
    node.error('Missing cmdb_ci in Spark payload - cannot trigger rescue', msg);
    return null;
}

if (!msg.description && !msg.shortDesc && !msg.workNotes) {
    node.warn('No description / short_description / work_notes in payload - AI summary will use placeholder');
}

node.log('Processing rescue for device name: ' + msg.deviceName);
return msg;

// Combine description + work_notes for richer AI context.
// Description = user problem; work_notes = troubleshooting history.
const parts = [];
if (msg.description) parts.push('ISSUE:\n' + msg.description);
if (msg.workNotes)   parts.push('TROUBLESHOOTING ALREADY ATTEMPTED:\n' + msg.workNotes);

const conversation = parts.length > 0
    ? parts.join('\n\n')
    : (msg.shortDesc || '');

// Stash for fallback if AI call fails
msg.rawConversation = conversation;

if (!conversation || conversation.trim().length === 0) {
    msg.summary = 'Spark escalation - no conversation context provided';
    msg.skipAI = true;
    return msg;
}

if (conversation.length <= 500) {
    msg.summary = conversation;
    msg.skipAI = true;
    node.log('Conversation already <= 500 chars, skipping AI');
    return msg;
}

const apiKey = env.get('OPENAI_API_KEY');
if (!apiKey) {
    node.error('OPENAI_API_KEY env var not set', msg);
    return null;
}

const model = env.get('OPENAI_MODEL') || 'gpt-5.4-mini';

const instructions = 'You are summarizing an IT support escalation. The input has two labeled sections: ISSUE (what the user reports) and TROUBLESHOOTING ALREADY ATTEMPTED (what the AI assistant tried before escalating). Produce a single-paragraph summary STRICTLY UNDER 450 CHARACTERS for a human technician about to take over. It MUST capture: (1) what is broken, (2) what has already been ruled out, (3) the most likely remaining cause if mentioned. Skip pleasantries, names, timestamps, and preamble. Output ONLY the summary text.';

msg.url = 'https://api.openai.com/v1/responses';
msg.method = 'POST';
msg.headers = {
    'Authorization': 'Bearer ' + apiKey,
    'Content-Type': 'application/json'
};
msg.payload = {
    model: model,
    instructions: instructions,
    input: conversation
};

msg.skipAI = false;
return msg;

function fallback(reason) {
    node.warn('AI summary failed (' + reason + '), falling back to truncated raw text');
    const fallbackText = (msg.rawConversation || 'Spark escalation - see ticket for details').substring(0, 500);
    msg.summary = fallbackText;
    return msg;
}

if (msg.statusCode && msg.statusCode >= 400) {
    return fallback('HTTP ' + msg.statusCode + ': ' + (typeof msg.payload === 'string' ? msg.payload.substring(0, 200) : JSON.stringify(msg.payload).substring(0, 200)));
}

let body;
try {
    body = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    return fallback('JSON parse error: ' + e.message);
}

let summary = null;

if (body.output_text && typeof body.output_text === 'string') {
    summary = body.output_text;
}

if (!summary && Array.isArray(body.output)) {
    for (const item of body.output) {
        if (item.type === 'message' && Array.isArray(item.content)) {
            for (const c of item.content) {
                if (c.type === 'output_text' && c.text) {
                    summary = c.text;
                    break;
                }
            }
        }
        if (summary) break;
    }
}

if (!summary) {
    return fallback('No summary text found in response: ' + JSON.stringify(body).substring(0, 300));
}

summary = summary.trim();

if (summary.length > 500) {
    node.warn('AI returned ' + summary.length + ' chars, truncating to 500');
    summary = summary.substring(0, 500);
}

msg.summary = summary;
node.log('AI summary (' + summary.length + ' chars): ' + summary);
return msg;

const body = JSON.parse(msg.payload);

if (!body.access_token) {
    node.error('No access_token in response', msg);
    return null;
}

node.log('Token received: ' + body.access_token.substring(0, 20) + '...');

msg.token = body.access_token;
return msg;

// Resolve the device name from Spark into Nexthink's collector.uid (UUID)
// before triggering the remote action.

if (!msg.deviceName) {
    node.error('Cannot resolve UID - msg.deviceName is empty', msg);
    return null;
}

// Stash the original hostname so we can log it later if useful
msg.deviceHostname = msg.deviceName;

const nqlQueryId = env.get('NEXTHINK_NQL_DEVICE_LOOKUP_ID') || '#resolve_device_uid_by_name';

msg.url = 'https://<your-tenant>.api.<region>.nexthink.cloud/api/v2/nql/execute';
msg.method = 'POST';
msg.headers = {
    'Authorization': 'Bearer ' + msg.token,
    'Content-Type': 'application/json',
    'Accept': 'application/json'
};
msg.payload = {
    queryId: nqlQueryId,
    parameters: {
        param0: msg.deviceHostname
    }
};

node.log('Looking up Nexthink UID for device name: ' + msg.deviceHostname);
return msg;

// Extract device.collector.uid from the NQL response.
// V2 shape per Nexthink docs:
//   { queryId, executedQuery, rows: <count>, data: [ { "device.collector.uid": "..." } ] }

if (msg.statusCode && msg.statusCode >= 400) {
    node.error('NQL lookup failed: HTTP ' + msg.statusCode + ' - ' + (typeof msg.payload === 'string' ? msg.payload.substring(0, 300) : JSON.stringify(msg.payload).substring(0, 300)), msg);
    return null;
}

let body;
try {
    body = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.error('Failed to parse NQL response: ' + e.message, msg);
    return null;
}

if (!Array.isArray(body.data) || body.data.length === 0) {
    node.error('No data rows for device "' + msg.deviceHostname + '". NQL response: ' + JSON.stringify(body).substring(0, 300), msg);
    return null;
}

const uid = body.data[0]['device.collector.uid'];

if (!uid) {
    node.error('device.collector.uid missing in row for "' + msg.deviceHostname + '". Row: ' + JSON.stringify(body.data[0]), msg);
    return null;
}

node.log('Resolved ' + msg.deviceHostname + ' → ' + uid);

// Overwrite deviceName with the UUID so Build Execute Payload uses the right value
msg.deviceName = uid;

return msg;

msg.headers = {
    'Authorization': 'Bearer ' + msg.token,
    'Content-Type': 'application/json',
    'Accept': '*/*'
};

const reason = msg.shortDesc
    ? `Spark escalation: ${msg.shortDesc}`
    : 'Spark escalation - Launching Rescue Session';

const externalRef = msg.callerId
    ? `SPARK-${msg.callerId}`
    : 'SPARK-UNKNOWN';

const remoteActionId = env.get('NEXTHINK_REMOTE_ACTION_ID') || '#escalate_spark_to_rescue_remote';

msg.payload = {
    remoteActionId: remoteActionId,
    devices: [msg.deviceName],   // <-- now contains the resolved UUID
    expiresInMinutes: 60,
    triggerInfo: {
        externalSource: 'Node-RED',
        reason: reason,
        externalReference: externalRef
    },
    params: {
        IssueSummary: msg.summary || 'Spark escalation - see ticket for details'
    }
};

node.log('Executing ' + remoteActionId + ' on UID ' + msg.deviceName + ' (hostname: ' + (msg.deviceHostname || 'unknown') + ') with summary: ' + (msg.summary || '').substring(0, 80) + '...');
return msg;

try {
    const body = JSON.parse(msg.payload);
    if (body.requestId) {
        node.log('Rescue triggered. Nexthink requestId: ' + body.requestId);
        msg.rescueRequestId = body.requestId;
    } else {
        node.warn('Unexpected execute response: ' + msg.payload);
    }
} catch (e) {
    node.error('Failed to parse execute response: ' + msg.payload, msg);
    return null;
}

return msg;
